	regaudit.[apuk_registeredvaluersatfirm],
	regaudit.[apuk_nonregisteredvaluersatfirm],
	regaudit.[apuk_amountofclientmoneyatfirm]

FROM [synapse_ce].[vwCaseregulatoryaudit] regaudit
	LEFT JOIN [synapse_ce].[systemuser] suser
		ON regaudit.[apuk_reviewerid] = suser.[systemuserid]
	LEFT JOIN [synapse_ce].[subject] subj
		ON regaudit.[apuk_primarysubject] = subj.[Id]
